assign C_out = carry[3];

endmodule

module full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

wire sum1;
wire C1;
wire C2;

// First XOR gate
xor(sum1, A, B);

// Second XOR gate
xor(S, sum1, C_in);

// First AND gate
and(C1, A, B);

// Second AND gate
and(C2, sum1, C_in);

// OR gate
or(C_out, C1, C2);

endmodule
