                if (|debounce_reg[k] == 0) begin
                    state[k] <= 0;
                end else if (&debounce_reg[k] == 1) begin
                    state[k] <= 1;
                end else begin
                    state[k] <= state[k];
                end
            end
        end
    end

endmodule
