     ce0_negedge <= ce0;

   //########################
   // Dual edge sampling
   //########################

   always @(posedge clk)
     if (ce0)
       din_sl <= din;
   always @(negedge clk)
     if (ce0_negedge)
       din_sh <= din;

   //########################
   // Aign pipeline
   //########################
   always @(posedge clk)
     if (ce1)
       dout <= {din_sh, din_sl};

endmodule
