  parameter PL_FAST_TRAIN = "FALSE",
  parameter REF_CLK_FREQ = 0,   parameter TCQ = 1

)
(

  input  wire        ref_clk,
  input  wire        sys_reset_n,
  output             delayed_sys_reset_n

);


  localparam         TBIT =  (PL_FAST_TRAIN == "FALSE") ?  ((REF_CLK_FREQ == 1) ? 20: (REF_CLK_FREQ == 0) ? 20 : 21) : 2;

