  always @(posedge ref_clk or negedge sys_reset_n) begin

    if (!sys_reset_n) begin

      reg_count_7_0 <= #TCQ 8'h0;
      reg_count_15_8 <= #TCQ 8'h0;
      reg_count_23_16 <= #TCQ 8'h0;

