  case (state)
    S0: out = O0;
    S1: out = O1;
    S2: out = O2;
    S3: out = O3;
    S4: out = O0;
    S5: out = O1;
    S6: out = O2;
    S7: out = O3;
  endcase
end

// update the state
always @ (posedge clk) begin
  state <= next_state;
end

endmodule

