    input Clock, Reset, Set, Load, Enable,
    input [Width-1:0] In,
    output reg [Width-1:0] Count
);

parameter Width = 32;
parameter Limited = 0;
parameter Down = 0;
parameter Initial = {Width{1'bx}};
parameter AsyncReset = 0;
parameter AsyncSet = 0;

wire NoLimit;

wire RegEnable;
wire [Width-1:0] RegIn;

assign NoLimit = !Limited;

